package com.openggf.game.soniccd.special;

import static com.openggf.game.soniccd.special.CdSpecialMath.divs;
import static com.openggf.game.soniccd.special.CdSpecialMath.muls;

/**
 * The floor's per-line vectors (start X, start Y, X step, Y step, as 16-bit words) for one
 * graphics operation, generated by {@code GenGfxTraceTbl} (scddisasm/src/Special Stage/Sub.asm:2399-2557) from the view.
 *
 * <p>Per line ({@code .GenLoop}): Z = line * sin(pitch) + FOV * cos(pitch); the left and right
 * screen edges (-128 and +127) are rotated by yaw, offset by the pitched view point and scaled
 * by camera Z / Z; start = left edge, step = right edge minus left edge (13.3 units over 256
 * pixels, read by the operation as a 5.11 per-pixel step). The first three lines are blank
 * (start 0,$FFF8; Sub.asm:2476-2481). Divides keep the 68000 {@code divs.w} overflow result.
 */
public final class CdStampTrace {
    private final int[] words = new int[CdStampFloor.IMAGE_HEIGHT * 4];

    public int x(int line) { return words[line * 4]; }
    public int y(int line) { return words[line * 4 + 1]; }
    public int dx(int line) { return words[line * 4 + 2]; }
    public int dy(int line) { return words[line * 4 + 3]; }

    /** Sets one line's four words (each masked to 16 bits); used to load a native table. */
    public void set(int line, int x, int y, int dx, int dy) {
        words[line * 4] = x & 0xFFFF;
        words[line * 4 + 1] = y & 0xFFFF;
        words[line * 4 + 2] = dx & 0xFFFF;
        words[line * 4 + 3] = dy & 0xFFFF;
    }

    /** {@code GenGfxTraceTbl}: the table for {@code view}. */
    public void generate(CdSpecialStageView view) {
        int fov = view.fov();
        int psin = view.pitchSin();
        int pcos = view.pitchCos();
        int ysin = view.yawSin();
        int ycos = view.yawCos();
        int camZ = view.cameraZ();
        int d0 = (view.cameraX() << 3) & 0xFFFF;
        int d1 = (view.cameraY() << 3) & 0xFFFF;
        int pcys = (short) (muls(pcos, ysin) >> 5);
        int pcyc = (short) (muls(pcos, ycos) >> 5);
        // FOV * sin(pitch) is a long, but the following muls.w reads only its low word.
        int psysfov = muls(muls(fov, psin), ysin) >> 5;
        int psycfov = muls(muls(fov, psin), ycos) >> 5;
        int pcfov = muls(fov, pcos);
        int a1 = muls(-128, ycos) << 3;
        int a2 = muls(-128, ysin) << 3;
        int a3 = muls(127, ycos) << 3;
        int a4 = muls(127, ysin) << 3;
        int fovCenter = (short) (fov + view.center());
        int centerX = (short) (muls(fovCenter, muls(psin, ysin) >> 5) >> 8);
        int centerY = (short) (muls(fovCenter, muls(psin, ycos) >> 5) >> 8);
        for (int line = 0; line < 3; line++) set(line, 0, 0xFFF8, 0, 0);
        int d2 = -3;
        for (int line = 3; line < CdStampFloor.IMAGE_HEIGHT; line++, d2--) {
            int z = (muls(d2, psin) + pcfov) >> 5;
            if (z == 0) z = 1;
            if ((short) z == 0) throw new IllegalStateException("Trace divisor low word is zero");
            int xs = edge(a1 - muls(pcys, d2) + psysfov, camZ, z) + d0 - centerX;
            int ys = edge(a2 + muls(pcyc, d2) - psycfov, camZ, z) + d1 + centerY;
            int xe = edge(a3 - muls(pcys, d2) + psysfov, camZ, z) + d0 - centerX;
            int ye = edge(a4 + muls(pcyc, d2) - psycfov, camZ, z) + d1 + centerY;
            set(line, xs, ys, xe - xs, ye - ys);
        }
    }

    private static int edge(int point, int camZ, int z) {
        return divs(muls(point >> 8, camZ), z);
    }
}
